import { chromium } from 'playwright';
import fs from 'node:fs';
import path from 'node:path';

const TARGET='https://www.statesideqm.com/collections/safety-rescue-climbing?preview_theme_id=158561894555';
const OUT='out/safety-browser-cert';
fs.mkdirSync(OUT,{recursive:true});
const report={target:TARGET,themeId:'158561894555',generatedAt:new Date().toISOString(),cases:[],failures:[]};
const cases=[{name:'desktop',viewport:{width:1440,height:1000},cols:3},{name:'mobile',viewport:{width:390,height:844},cols:2}];

function addFail(c,msg,data){const x=data===undefined?msg:`${msg}: ${JSON.stringify(data)}`;c.failures.push(x);report.failures.push(`${c.name}: ${x}`)}
async function choiceLocator(page,value){const all=page.locator('[data-sq-ucp-group] input[data-sq-ucp-value]');for(let i=0,n=await all.count();i<n;i++){if((await all.nth(i).getAttribute('value'))===value)return all.nth(i)}return null}
async function installProbe(page){await page.addInitScript(()=>{window.__sqSafetyFlash=[];let last='';const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)!==0&&r.width>2&&r.height>2};const scan=()=>{const m=document.querySelector('#MainContent');if(!m)return;const r=m.querySelector('.sq-refine-v3-results');const gs=[...m.querySelectorAll('.product-grid')].filter(vis),outside=gs.filter(g=>!r||!r.contains(g));if(outside.length){const sig=`${location.pathname}${location.search}|${gs.length}|${outside.length}`;if(sig!==last){last=sig;window.__sqSafetyFlash.push({t:Math.round(performance.now()),url:location.href,visible:gs.length,outside:outside.length})}}};const tick=()=>{try{scan()}catch{}requestAnimationFrame(tick)};requestAnimationFrame(tick)})}
async function ready(page){await page.waitForSelector('#MainContent',{timeout:90000});await page.waitForFunction(()=>document.querySelector('#MainContent')?.dataset.sqRefineV3Ready==='true',{timeout:90000});await page.waitForFunction(()=>window.__sqUniformColor?.ready===true,{timeout:90000});await page.waitForSelector('[data-sq-ucp-group] input[data-sq-ucp-value]',{timeout:90000});await page.waitForTimeout(700)}
async function snap(page,label){return page.evaluate(label=>{const vis=e=>{if(!e)return false;const s=getComputedStyle(e),r=e.getBoundingClientRect();return s.display!=='none'&&s.visibility!=='hidden'&&Number(s.opacity||1)!==0&&r.width>2&&r.height>2};const m=document.querySelector('#MainContent'),side=m?.querySelector('.sq-refine-v3-sidebar'),res=m?.querySelector('.sq-refine-v3-results');const sums=[...(side?.querySelectorAll('details>summary')||[])].map(x=>(x.textContent||'').replace(/\s+/g,' ').trim());const groups=[...(side?.querySelectorAll('[data-sq-ucp-group]')||[])];const choices=groups[0]?[...groups[0].querySelectorAll('input[data-sq-ucp-value]')].map(i=>({value:i.value,checked:i.checked,label:(i.closest('label')?.querySelector('span')?.textContent||'').trim()})):[];const grids=[...(m?.querySelectorAll('.product-grid')||[])].filter(vis),outside=grids.filter(g=>!res?.contains(g)),inside=grids.filter(g=>res?.contains(g));const filtered=res?.querySelector('[data-sq-ucp-results]');const fg=filtered?.querySelector('.product-grid');const cards=fg?[...fg.querySelectorAll(':scope > [data-product-id]')].filter(vis):[];const normal=[...(res?.querySelectorAll('.product-grid > .product-grid__item')||[])].filter(vis);const grid=fg||inside[0];const cols=grid?getComputedStyle(grid).gridTemplateColumns.split(' ').filter(Boolean).length:0;const u=new URL(location.href),api=window.__sqUniformColor||{};return{label,url:location.href,theme:window.Shopify?.theme?{id:String(window.Shopify.theme.id||''),role:String(window.Shopify.theme.role||'')}:null,refineReady:m?.dataset.sqRefineV3Ready||null,colorReady:m?.dataset.sqUniformColorReady||null,summaryCount:sums.filter(x=>x==='Shop by Color / Pattern').length,colorGroupCount:groups.length,choices,visibleGridCount:grids.length,outsideGridCount:outside.length,insideGridCount:inside.length,filteredVisible:vis(filtered),filteredCount:cards.length,filteredIds:cards.map(x=>String(x.dataset.productId||'')),normalCount:normal.length,cols,overflow:document.documentElement.scrollWidth>window.innerWidth+3,sqRoot:u.searchParams.get('sq_root'),sqUcp:u.searchParams.getAll('sq_ucp'),sqPerPage:u.searchParams.get('sq_per_page'),sqViewPage:u.searchParams.get('sq_view_page'),sizes:[...(m?.querySelectorAll('input[name="sq_per_page_control"]')||[])].map(i=>({value:i.value,checked:i.checked})),pager:[...(filtered?.querySelectorAll('.sq-refine-v3-pager a')||[])].map(a=>({text:a.textContent.trim(),href:a.href})),api:{ready:!!api.ready,total:api.total,matches:api.matches,page:api.page,pageSize:api.pageSize,resultIds:(api.resultIds||[]).map(String),choices:api.choices||[],error:api.error||null},flash:window.__sqSafetyFlash||[]}},label)}
function baseChecks(c,s,cols,phase,{allowFlash=false}={}){if(s.theme?.id&&s.theme.id!=='158561894555')addFail(c,`${phase} wrong theme`,s.theme);if(s.theme?.role==='main')addFail(c,`${phase} is live/main theme`,s.theme);if(s.refineReady!=='true'||!s.api.ready)addFail(c,`${phase} V3/color code not ready`);if(s.summaryCount!==1)addFail(c,`${phase} Shop by Color / Pattern summary count`,s.summaryCount);if(s.colorGroupCount!==1)addFail(c,`${phase} color group count`,s.colorGroupCount);if(!s.choices.length)addFail(c,`${phase} choices empty`);if(s.outsideGridCount!==0)addFail(c,`${phase} visible legacy/native grid outside V3 results`,s.outsideGridCount);if(s.visibleGridCount!==1)addFail(c,`${phase} visible grid count`,s.visibleGridCount);if(s.cols!==cols)addFail(c,`${phase} columns`,{got:s.cols,want:cols});if(s.overflow)addFail(c,`${phase} horizontal overflow`);if(s.sqRoot==='uniforms')addFail(c,`${phase} leaked sq_root=uniforms`);const vals=s.sizes.map(x=>x.value).sort();if(JSON.stringify(vals)!==JSON.stringify(['100','250','50']))addFail(c,`${phase} page-size controls`,vals);if(!allowFlash&&s.flash.length)addFail(c,`${phase} legacy/duplicate grid flash detected`,s.flash)}
async function shot(page,name,phase){await page.screenshot({path:path.join(OUT,`${name}-${phase}.png`),fullPage:true})}

async function run(browser,spec){const ctx=await browser.newContext({viewport:spec.viewport,recordVideo:{dir:path.join(OUT,`${spec.name}-video`)}}),page=await ctx.newPage();page.setDefaultTimeout(60000);page.setDefaultNavigationTimeout(120000);const c={name:spec.name,viewport:spec.viewport,phases:{},failures:[],consoleErrors:[],pageErrors:[],requestFailures:[]};report.cases.push(c);await installProbe(page);page.on('console',m=>{if(m.type()==='error'){const loc=m.location();const text=m.text(),url=loc?.url||'';if(url.includes('statesideqm.com')||text.includes('[SQ'))c.consoleErrors.push({text,url})}});page.on('pageerror',e=>c.pageErrors.push(String(e)));page.on('requestfailed',r=>{if(r.url().includes('statesideqm.com'))c.requestFailures.push({url:r.url(),error:r.failure()?.errorText||''})});try{const resp=await page.goto(TARGET,{waitUntil:'domcontentloaded'});c.httpStatus=resp?.status()||null;if(!resp||resp.status()>=400)addFail(c,'initial HTTP failure',c.httpStatus);await ready(page);let s=await snap(page,'initial');c.phases.initial=s;baseChecks(c,s,spec.cols,'initial');if(!s.normalCount)addFail(c,'initial normal products missing');await shot(page,c.name,'initial');const choice=[...(s.api.choices||[])].filter(x=>Number(x.count)>0).sort((a,b)=>Number(b.count)-Number(a.count))[0];if(!choice)throw new Error('No populated color/pattern choice available');c.selectedChoice=choice;let box=await choiceLocator(page,choice.value);if(!box)throw new Error(`Could not locate checkbox ${choice.value}`);await box.scrollIntoViewIfNeeded();await Promise.all([page.waitForURL(u=>u.searchParams.getAll('sq_ucp').includes(choice.value),{timeout:45000}),box.check()]);await ready(page);s=await snap(page,'selected');c.phases.selected=s;baseChecks(c,s,spec.cols,'selected');if(!s.sqUcp.includes(choice.value))addFail(c,'selected URL missing sq_ucp',s.sqUcp);if(!s.choices.find(x=>x.value===choice.value)?.checked)addFail(c,'selected checkbox not checked');if(!(Number(s.api.matches)>0))addFail(c,'selected filter has no matches',s.api.matches);if(!s.filteredVisible||!s.filteredCount)addFail(c,'matching products did not render');if(JSON.stringify(s.filteredIds)!==JSON.stringify(s.api.resultIds))addFail(c,'rendered filtered product IDs differ from API result IDs',{rendered:s.filteredIds,api:s.api.resultIds});if(s.outsideGridCount!==0||s.visibleGridCount!==1)addFail(c,'filtered duplicate/native grid leak',{visible:s.visibleGridCount,outside:s.outsideGridCount});await shot(page,c.name,'selected');

// Page size 100 while color filter is active.
const size100=page.locator('input[name="sq_per_page_control"][value="100"]').first();if(await size100.count()){await Promise.all([page.waitForURL(u=>u.searchParams.get('sq_per_page')==='100'&&u.searchParams.get('sq_view_page')==='1',{timeout:45000}),size100.check()]);await ready(page);s=await snap(page,'page-size-100');c.phases['page-size-100']=s;baseChecks(c,s,spec.cols,'page-size-100');if(Number(s.api.pageSize)!==100)addFail(c,'page-size API did not become 100',s.api.pageSize);if(!s.sizes.find(x=>x.value==='100')?.checked)addFail(c,'100 page-size radio not checked');if(s.filteredCount!==Math.min(100,Number(s.api.matches)||0))addFail(c,'100 page-size rendered wrong count',{rendered:s.filteredCount,matches:s.api.matches});await shot(page,c.name,'page-size-100')}else addFail(c,'100 products/page control missing');

// Pagination while filtered.
if(Number(s.api.matches)>Number(s.api.pageSize||100)){const next=page.locator('[data-sq-ucp-results] .sq-refine-v3-pager a').filter({hasText:/^Next$/i}).first();if(await next.count()){const first=s.filteredIds[0];await Promise.all([page.waitForURL(u=>u.searchParams.get('sq_view_page')==='2',{timeout:45000}),next.click()]);await ready(page);s=await snap(page,'page-2');c.phases['page-2']=s;baseChecks(c,s,spec.cols,'page-2');if(Number(s.api.page)!==2)addFail(c,'pagination API did not become page 2',s.api.page);if(!s.sqUcp.includes(choice.value))addFail(c,'pagination lost sq_ucp');if(s.filteredIds[0]&&first===s.filteredIds[0])addFail(c,'pagination first product did not change');await shot(page,c.name,'page-2')}else addFail(c,'Next pager missing despite multiple pages',{matches:s.api.matches,pageSize:s.api.pageSize})}else c.paginationNotApplicable={matches:s.api.matches,pageSize:s.api.pageSize};

// Clear checkbox; must remove sq_ucp and restore one normal grid.
box=await choiceLocator(page,choice.value);if(!box)throw new Error('Selected checkbox not found before clear');await box.scrollIntoViewIfNeeded();await Promise.all([page.waitForURL(u=>!u.searchParams.has('sq_ucp'),{timeout:45000}),box.uncheck()]);await ready(page);s=await snap(page,'cleared');c.phases.cleared=s;baseChecks(c,s,spec.cols,'cleared');if(s.sqUcp.length)addFail(c,'clear left sq_ucp',s.sqUcp);if(s.choices.some(x=>x.checked))addFail(c,'clear left color checkbox checked');if(!s.normalCount)addFail(c,'clear did not restore normal products');await shot(page,c.name,'cleared');

// Explicit regression: inject stale sq_root=uniforms, then selecting a Safety color must strip it.
await page.goto(TARGET,{waitUntil:'domcontentloaded'});await ready(page);await page.evaluate(()=>{const u=new URL(location.href);u.searchParams.set('sq_root','uniforms');history.replaceState({},'',u.pathname+u.search)});box=await choiceLocator(page,choice.value);if(!box)throw new Error('Color checkbox unavailable for stale-root test');await box.scrollIntoViewIfNeeded();await Promise.all([page.waitForURL(u=>u.searchParams.has('sq_ucp'),{timeout:45000}),box.check()]);await ready(page);s=await snap(page,'stale-root');c.phases['stale-root']=s;baseChecks(c,s,spec.cols,'stale-root');if(s.sqRoot==='uniforms')addFail(c,'stale sq_root=uniforms survived Safety color selection');if(!s.sqUcp.includes(choice.value))addFail(c,'stale-root test failed to set sq_ucp');await shot(page,c.name,'stale-root');

if(c.consoleErrors.length)addFail(c,'browser console errors',c.consoleErrors);if(c.pageErrors.length)addFail(c,'browser/runtime errors',c.pageErrors)}catch(e){addFail(c,'uncaught certification error',e?.stack||String(e));try{await shot(page,c.name,'failure')}catch{}}finally{await ctx.close()}}

const browser=await chromium.launch({headless:true});for(const spec of cases)await run(browser,spec);await browser.close();report.passed=report.failures.length===0;fs.writeFileSync(path.join(OUT,'report.json'),JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));if(!report.passed)process.exitCode=2;
